using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.IO.Compression;
using ReplyAI.Updates;
class UpdateTests {
 static int checks;static string root;
 static void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}
 static void Reject(Action action,string name){bool failed=false;try{action();}catch{failed=true;}Check(failed,name);}
 static string Fixture(string name){string dir=Path.Combine(root,name);Directory.CreateDirectory(Path.Combine(dir,"engine-v1.9"));File.WriteAllText(Path.Combine(dir,"ReplyAI.exe"),"new");File.WriteAllText(Path.Combine(dir,"engine-v1.9/parole-engine.exe"),"engine");var m=new PackageManifest{Product="Reply AI",Version="2.1.0",Files=new List<PackageFile>()};foreach(string file in Directory.GetFiles(dir,"*",SearchOption.AllDirectories))m.Files.Add(new PackageFile{Path=file.Substring(dir.Length+1).Replace('\\','/'),Sha256=UpdatePackage.Hash(file)});File.WriteAllText(Path.Combine(dir,"update-manifest.json"),UpdatePackage.Json().Serialize(m));return dir;}
 static int Main(string[] args){try{root=Path.Combine(Path.GetFullPath(args[0]),"updates-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);Check(UpdatePackage.ParseVersion("v2.10.0")>UpdatePackage.ParseVersion("2.9.0"),"numeric version ordering");Reject(()=>UpdatePackage.ParseVersion("main"),"invalid version");foreach(string path in new[]{"../ReplyAI.exe","engine-v1.9/../../bad","C:/ReplyAI.exe","engine-v1.9/NUL.txt","workspace.json","engine-v1.9/a:secret"})Reject(()=>UpdatePackage.Relative(path),"reject path "+path);
 string stage=Fixture("stage");UpdatePackage.Verify(stage,"2.1.0");Check(true,"valid manifest");Reject(()=>UpdatePackage.Verify(stage,"2.2.0"),"version mismatch");string target=Path.Combine(root,"install");Directory.CreateDirectory(target);File.WriteAllText(Path.Combine(target,"ReplyAI.exe"),"old");File.WriteAllText(Path.Combine(target,"workspace.json"),"private");int copies=0;Reject(()=>UpdatePackage.Install(stage,target,Path.Combine(root,"rollback"),"2.1.0",(a,b)=>{File.Copy(a,b,true);if(++copies==2)throw new IOException("injected");}),"copy failure");Check(File.ReadAllText(Path.Combine(target,"ReplyAI.exe"))=="old","rollback restores previous executable");Check(!File.Exists(Path.Combine(target,"engine-v1.9/parole-engine.exe")),"rollback removes newly added file");UpdatePackage.Install(stage,target,Path.Combine(root,"backup"),"2.1.0");Check(File.ReadAllText(Path.Combine(target,"ReplyAI.exe"))=="new","install replaces executable");Check(File.ReadAllText(Path.Combine(target,"workspace.json"))=="private","user data untouched");
 string zip=Path.Combine(root,"good.zip");using(var archive=ZipFile.Open(zip,ZipArchiveMode.Create))foreach(string f in Directory.GetFiles(stage,"*",SearchOption.AllDirectories))archive.CreateEntryFromFile(f,"ReplyAI/"+f.Substring(stage.Length+1).Replace('\\','/'));UpdatePackage.Extract(zip,Path.Combine(root,"extracted"),"2.1.0",UpdatePackage.Hash(zip));Check(true,"verified ZIP extracted");Reject(()=>UpdatePackage.Extract(zip,Path.Combine(root,"wrong"),"2.1.0",new string('0',64)),"wrong archive hash");string evil=Path.Combine(root,"evil.zip");using(var a=ZipFile.Open(evil,ZipArchiveMode.Create))a.CreateEntry("ReplyAI/../escape.txt");Reject(()=>UpdatePackage.Extract(evil,Path.Combine(root,"evil"),"2.1.0",UpdatePackage.Hash(evil)),"ZIP traversal");File.WriteAllText(Path.Combine(stage,"ReplyAI.exe"),"tampered");Reject(()=>UpdatePackage.Verify(stage,"2.1.0"),"tampered payload");Console.WriteLine(checks+" updater checks passed.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
}
